        "قد نحدّث هذه الشروط عند تغير الخدمة أو نموذج الأعمال أو المخاطر أو المزودين أو القانون. يحدد التاريخ والإصدار أعلاه الشروط الحالية. إذا أثر التغيير جوهريًا على المستخدمين الحاليين فسنقدم إشعارًا إضافيًا معقولًا قبل نفاذه حيث يلزم. استمرار الاستخدام بعد تاريخ السريان يعني تطبيق الشروط المحدثة مع مراعاة القانون الإلزامي.",
