      "Adună toate tipurile de amintiri în aceeași cronologie.",
      "Συγκέντρωσε κάθε είδους ανάμνηση στο ίδιο χρονολόγιο.",
      "Sakupi sve vrste uspomena u istoj vremenskoj liniji događaja.",
